<!-- Chart.js Initialization -->
<!-- ============================================================ -->
<script>
const CHART_DATA = {json.dumps(chart_data)};

Chart.defaults.color = '#8b8fa3';
Chart.defaults.borderColor = '#2e3345';
Chart.defaults.font.family = 'Inter, -apple-system, sans-serif';

// 1. Winner Distribution (Doughnut)
new Chart(document.getElementById('chartWinnerDist'), {{
  type: 'doughnut',
  data: {{
    labels: ['White Wins', 'Black Wins', 'Draw'],
    datasets: [{{
      data: [CHART_DATA.winner_distribution.values[CHART_DATA.winner_distribution.labels.indexOf('white')] || 0,
             CHART_DATA.winner_distribution.values[CHART_DATA.winner_distribution.labels.indexOf('black')] || 0,
             CHART_DATA.winner_distribution.values[CHART_DATA.winner_distribution.labels.indexOf('draw')] || 0],
      backgroundColor: ['#e2e8f0', '#4a5568', '#a0aec0'],
      borderWidth: 0
    }}]
  }},
  options: {{
    responsive: true,
    plugins: {{
      legend: {{ position: 'bottom' }},
      tooltip: {{ callbacks: {{ label: (ctx) => `${{ctx.label}}: ${{ctx.raw.toLocaleString()}} (${{(ctx.raw / {total_games} * 100).toFixed(1)}}%)` }} }}
    }}
  }}
}});

// 2. Victory Status (Doughnut)
const vsColors = {{ mate: '#f6ad55', resign: '#fc8181', outoftime: '#63b3ed', draw: '#a0aec0' }};
const vsLabels = CHART_DATA.victory_status.labels;
const vsValues = CHART_DATA.victory_status.values;
new Chart(document.getElementById('chartVictoryStatus'), {{
  type: 'doughnut',
  data: {{
    labels: vsLabels,
    datasets: [{{
      data: vsValues,
      backgroundColor: vsLabels.map(l => vsColors[l] || '#7b68ee'),
      borderWidth: 0
    }}]
  }},
  options: {{
    responsive: true,
    plugins: {{
      legend: {{ position: 'bottom' }},
      tooltip: {{ callbacks: {{ label: (ctx) => `${{ctx.label}}: ${{ctx.raw.toLocaleString()}} (${{(ctx.raw / {total_games} * 100).toFixed(1)}}%)` }} }}
    }}
  }}
}});

// 3. Color by Victory Status (grouped bar)
const vStatusLabels = Object.keys(CHART_DATA.color_by_vstatus);
new Chart(document.getElementById('chartColorVStatus'), {{
  type: 'bar',
  data: {{
    labels: vStatusLabels.map(l => l.charAt(0).toUpperCase() + l.slice(1)),
    datasets: [
      {{ label: 'White', data: vStatusLabels.map(l => CHART_DATA.color_by_vstatus[l].white), backgroundColor: '#e2e8f0', borderRadius: 4 }},
      {{ label: 'Black', data: vStatusLabels.map(l => CHART_DATA.color_by_vstatus[l].black), backgroundColor: '#4a5568', borderRadius: 4 }}
    ]
  }},
  options: {{
    responsive: true,
    plugins: {{ legend: {{ position: 'top' }} }},
    scales: {{
      y: {{ beginAtZero: true, max: 100, title: {{ display: true, text: 'Win % (Decisive)' }} }},
      x: {{ title: {{ display: true, text: 'Victory Status' }} }}
    }}
  }}
}});

// 4. Color by Rating Bracket
const bracketLabels = Object.keys(CHART_DATA.color_by_bracket);
new Chart(document.getElementById('chartColorBracket'), {{
  type: 'bar',
  data: {{
    labels: bracketLabels,
    datasets: [
      {{ label: 'White Win %', data: bracketLabels.map(b => CHART_DATA.color_by_bracket[b].white), backgroundColor: '#e2e8f0', borderRadius: 4 }},
      {{ label: 'Black Win %', data: bracketLabels.map(b => CHART_DATA.color_by_bracket[b].black), backgroundColor: '#4a5568', borderRadius: 4 }}
    ]
  }},
