  .container {{ max-width: 1200px; margin: 0 auto; padding: 40px 24px; }}
  h1 {{
    font-size: 2.2rem;
    font-weight: 800;
    letter-spacing: -0.03em;
    background: linear-gradient(135deg, var(--accent), var(--accent2));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    margin-bottom: 8px;
  }}
  h2 {{
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--accent);
    margin: 48px 0 16px;
    padding-bottom: 8px;
    border-bottom: 2px solid var(--border);
  }}
  h3 {{
    font-size: 1.15rem;
    font-weight: 600;
    color: var(--text);
    margin: 28px 0 12px;
  }}
  .subtitle {{ color: var(--text-dim); font-size: 1.05rem; margin-bottom: 32px; }}
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 16px;
    margin: 20px 0 32px;
  }}
  .kpi-card {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 20px;
  }}
  .kpi-label {{ font-size: 0.8rem; color: var(--text-dim); text-transform: uppercase; letter-spacing: 0.05em; margin-bottom: 4px; }}
  .kpi-value {{ font-size: 1.8rem; font-weight: 700; }}
  .kpi-sub {{ font-size: 0.85rem; color: var(--text-dim); margin-top: 4px; }}
  .chart-row {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin: 20px 0;
  }}
  .chart-box {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 20px;
  }}
  .chart-box.full {{ grid-column: 1 / -1; }}
  .chart-box h4 {{ font-size: 0.95rem; color: var(--text-dim); margin-bottom: 12px; font-weight: 500; }}
  .chart-container {{ position: relative; width: 100%; }}
  .chart-container canvas {{ width: 100% !important; }}
  table {{
    width: 100%;
    border-collapse: collapse;
    margin: 16px 0;
    font-size: 0.9rem;
  }}
  th, td {{
    padding: 10px 14px;
    text-align: left;
    border-bottom: 1px solid var(--border);
  }}
  th {{
    background: var(--surface2);
    color: var(--text-dim);
    font-weight: 600;
    text-transform: uppercase;
    font-size: 0.75rem;
    letter-spacing: 0.05em;
  }}
  td {{ color: var(--text); }}
  tr:hover td {{ background: var(--surface2); }}
  .highlight {{ color: var(--accent2); font-weight: 600; }}
  .highlight-warn {{ color: var(--resign-color); font-weight: 600; }}
  .stat-block {{
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 20px;
    margin: 16px 0;
  }}
  .finding {{
    background: var(--surface);
    border-left: 4px solid var(--accent);
    border-radius: 0 12px 12px 0;
    padding: 16px 20px;
    margin: 12px 0;
  }}
  .finding strong {{ color: var(--accent2); }}
  p {{ margin: 8px 0; color: var(--text); }}
  .footnote {{ font-size: 0.8rem; color: var(--text-dim); margin-top: 48px; padding-top: 16px; border-top: 1px solid var(--border); }}
  @media (max-width: 768px) {{
    .chart-row {{ grid-template-columns: 1fr; }}
    h1 {{ font-size: 1.6rem; }}
    .kpi-grid {{ grid-template-columns: 1fr 1fr; }}
  }}
</style>
</head>
<body>
<div class="container">

<h1>Lichess Chess Game Analytics</h1>
<p class="subtitle">Patterns of Victory, Openings, and Player Dynamics &mdash; Analysis of {total_games:,} games</p>

<!-- ============================================================ -->
<h2 id="overview">Dataset Overview &amp; Game Distribution</h2>
<!-- ============================================================ -->

<div class="kpi-grid">
  <div class="kpi-card">
    <div class="kpi-label">Total Games</div>
    <div class="kpi-value">{total_games:,}</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-label">Rated Games</div>
    <div class="kpi-value">{rated_pct:.1f}%</div>
    <div class="kpi-sub">{rated_count:,} games</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-label">Unrated Games</div>
    <div class="kpi-value">{unrated_pct:.1f}%</div>
    <div class="kpi-sub">{unrated_count:,} games</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-label">Avg. Game Length</div>
    <div class="kpi-value">{avg_game_length}</div>
    <div class="kpi-sub">half-moves (plies)</div>
  </div>
</div>

<div class="chart-row">
  <div class="chart-box">
    <h4>Game Outcome Distribution</h4>
    <div class="chart-container"><canvas id="chartWinnerDist"></canvas></div>
  </div>
  <div class="chart-box">
    <h4>Victory Status Breakdown</h4>
    <div class="chart-container"><canvas id="chartVictoryStatus"></canvas></div>
  </div>
</div>

<div class="stat-block">
  <p>Of the <strong>{total_games:,}</strong> games analyzed, <strong>{rated_count:,}</strong> ({rated_pct:.1f}%) were rated and <strong>{unrated_count:,}</strong> ({unrated_pct:.1f}%) were casual.
  White won <strong>{white_wins:,}</strong> games ({white_win_rate_overall}% overall), Black won <strong>{black_wins:,}</strong> ({black_win_rate_overall}%), and <strong>{draw_count:,}</strong> ended in a draw ({draw_pct}%).
  The most common victory status was <strong>resignation</strong> at {victory_status_pct.get('resign', 0)}%, followed by <strong>mate</strong> at {victory_status_pct.get('mate', 0)}%, <strong>outoftime</strong> at {victory_status_pct.get('outoftime', 0)}%, and <strong>draw</strong> at {victory_status_pct.get('draw', 0)}%.</p>
</div>

<!-- ============================================================ -->
<h2 id="color-advantage">White vs. Black: The First-Move Advantage</h2>
<!-- ============================================================ -->

<div class="kpi-grid">
  <div class="kpi-card">
    <div class="kpi-label">White Win Rate (Decisive)</div>
    <div class="kpi-value" style="color: #f0f0f0">{white_win_rate_decisive}%</div>
    <div class="kpi-sub">{white_wins:,} wins out of {decisive_count:,} decisive games</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-label">Black Win Rate (Decisive)</div>
    <div class="kpi-value" style="color: #718096">{black_win_rate_decisive}%</div>
    <div class="kpi-sub">{black_wins:,} wins out of {decisive_count:,} decisive games</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-label">White's Edge</div>
    <div class="kpi-value" style="color: var(--accent2)">+{round(white_win_rate_decisive - black_win_rate_decisive, 1)}pp</div>
    <div class="kpi-sub">percentage points above 50%</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-label">Draw Rate</div>
    <div class="kpi-value" style="color: #a0aec0">{draw_pct}%</div>
    <div class="kpi-sub">{draw_count:,} games</div>
  </div>
</div>

<h3>White Advantage by Victory Status</h3>
<div class="chart-row">
  <div class="chart-box full">
    <h4>White vs. Black Win Rate by How the Game Ended (Decisive Games Only)</h4>
    <div class="chart-container"><canvas id="chartColorVStatus"></canvas></div>
  </div>
</div>

<div class="stat-block">
  <p>White's first-move advantage manifests differently across victory statuses.
  In checkmate endings, White wins {color_by_vstatus.get('mate', {}).get('white', 'N/A')}% vs. Black's {color_by_vstatus.get('mate', {}).get('black', 'N/A')}%
  ({color_by_vstatus.get('mate', {}).get('total', 0):,} decisive games).
  In resignations, White wins {color_by_vstatus.get('resign', {}).get('white', 'N/A')}% vs. {color_by_vstatus.get('resign', {}).get('black', 'N/A')}%
  ({color_by_vstatus.get('resign', {}).get('total', 0):,} games).
  Timeout outcomes favor White at {color_by_vstatus.get('outoftime', {}).get('white', 'N/A')}% vs. {color_by_vstatus.get('outoftime', {}).get('black', 'N/A')}%
  ({color_by_vstatus.get('outoftime', {}).get('total', 0):,} games).</p>
</div>

<h3>White Advantage by Rating Bracket</h3>
<div class="chart-row">
  <div class="chart-box full">
    <h4>White vs. Black Win Rate by Average Player Rating (Decisive Games)</h4>
    <div class="chart-container"><canvas id="chartColorBracket"></canvas></div>
  </div>
</div>

<div class="stat-block">
  <p>White's advantage varies across rating brackets. At lower ratings the first-move advantage tends to be more pronounced as players are less equipped to neutralize White's initiative. The data shows the following breakdown:</p>
</div>

<table>
<tr><th>Rating Bracket</th><th>Games</th><th>White Win %</th><th>Black Win %</th><th>White Edge</th></tr>
{''.join(f'<tr><td>{b}</td><td>{color_by_bracket.get(b, {}).get("total", 0):,}</td><td>{color_by_bracket.get(b, {}).get("white", "N/A")}%</td><td>{color_by_bracket.get(b, {}).get("black", "N/A")}%</td><td class="highlight">+{round(color_by_bracket.get(b, {}).get("white", 0) - color_by_bracket.get(b, {}).get("black", 0), 1)}pp</td></tr>' for b in bracket_order if b in color_by_bracket)}
</table>

<h3>White Advantage by Time Control</h3>
<div class="chart-row">
  <div class="chart-box full">
    <h4>White vs. Black Win Rate by Time Control (Top 8, Decisive Games)</h4>
    <div class="chart-container"><canvas id="chartColorTC"></canvas></div>
  </div>
</div>

<table>
<tr><th>Time Control</th><th>Decisive Games</th><th>White Win %</th><th>Black Win %</th><th>White Edge</th></tr>
{''.join(f'<tr><td>{tc}</td><td>{color_by_tc[tc]["total"]:,}</td><td>{color_by_tc[tc]["white"]}%</td><td>{color_by_tc[tc]["black"]}%</td><td class="highlight">+{round(color_by_tc[tc]["white"] - color_by_tc[tc]["black"], 1)}pp</td></tr>' for tc in top_tcs if tc in color_by_tc)}
</table>

<!-- ============================================================ -->
<h2 id="rating-analysis">Rating Dynamics and Their Impact on Outcomes</h2>
<!-- ============================================================ -->

<div class="kpi-grid">
  <div class="kpi-card">
    <div class="kpi-label">Mean White Rating</div>
    <div class="kpi-value">{rating_stats['white']['mean']}</div>
    <div class="kpi-sub">&sigma; = {rating_stats['white']['std']}</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-label">Mean Black Rating</div>
    <div class="kpi-value">{rating_stats['black']['mean']}</div>
    <div class="kpi-sub">&sigma; = {rating_stats['black']['std']}</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-label">Rating Range</div>
    <div class="kpi-value">{rating_stats['white']['min']}&ndash;{rating_stats['white']['max']}</div>
    <div class="kpi-sub">White players</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-label">Correlation (Diff &rarr; Win)</div>
    <div class="kpi-value" style="color: var(--accent2)">{correlation}</div>
    <div class="kpi-sub">|rating diff| vs. higher-rated wins</div>
  </div>
</div>

<h3>Rating Distribution</h3>
<div class="chart-row">
  <div class="chart-box full">
    <h4>Player Rating Distribution (White vs. Black)</h4>
    <div class="chart-container"><canvas id="chartRatingDist"></canvas></div>
  </div>
</div>

<h3>Rating Differential &amp; Win Probability</h3>
<div class="chart-row">
  <div class="chart-box full">
    <h4>Higher-Rated Player Win Rate by Absolute Rating Differential</h4>
    <div class="chart-container"><canvas id="chartDiffImpact"></canvas></div>
  </div>
</div>

<div class="stat-block">
  <p>The relationship between rating differential and win probability is monotonic and strong. When ratings are nearly equal (0&ndash;24 point gap), the higher-rated player wins only {diff_impact.get('0-24', {}).get('pct', 'N/A')}% of the time &mdash; barely above coin-flip territory. But with a 200&ndash;299 point advantage, that climbs to {diff_impact.get('200-299', {}).get('pct', 'N/A')}%, and at 500+ points the higher-rated player wins over {diff_impact.get('500-749', {}).get('pct', 'N/A')}% of games. The Pearson correlation between absolute rating difference and higher-rated player winning is <strong>{correlation}</strong>.</p>
</div>

<table>
<tr><th>Rating Gap</th><th>Games</th><th>Higher-Rated Win %</th></tr>
{''.join(f'<tr><td>{label}</td><td>{diff_impact[label]["count"]:,}</td><td class="highlight">{diff_impact[label]["pct"]}%</td></tr>' for label in diff_labels if label in diff_impact)}
</table>

<h3>Game Length by Rating Tier</h3>
<div class="chart-row">
  <div class="chart-box full">
    <h4>Average Turns by Average Player Rating</h4>
    <div class="chart-container"><canvas id="chartLengthTier"></canvas></div>
  </div>
</div>

<table>
<tr><th>Rating Bracket</th><th>Games</th><th>Avg. Turns</th><th>Median Turns</th></tr>
{''.join(f'<tr><td>{b}</td><td>{length_by_tier[b]["count"]:,}</td><td>{length_by_tier[b]["mean"]}</td><td>{length_by_tier[b]["median"]}</td></tr>' for b in bracket_order if b in length_by_tier)}
</table>

<h3>Game Length by Victory Status</h3>
<table>
<tr><th>Victory Status</th><th>Games</th><th>Avg. Turns</th><th>Median Turns</th></tr>
{''.join(f'<tr><td>{vs}</td><td>{length_by_vstatus[vs]["count"]:,}</td><td>{length_by_vstatus[vs]["mean"]}</td><td>{length_by_vstatus[vs]["median"]}</td></tr>' for vs in ['mate', 'resign', 'outoftime', 'draw'])}
</table>

<!-- ============================================================ -->
<h2 id="opening-strategy">Opening Analysis: Popular Openings and Their Success Rates</h2>
<!-- ============================================================ -->

<h3>Top 15 Openings by Frequency</h3>
<div class="chart-row">
  <div class="chart-box full">
    <h4>Win Rate by Opening (Top 15 by Frequency, Decisive Games)</h4>
    <div class="chart-container"><canvas id="chartOpeningWin"></canvas></div>
  </div>
</div>

<table>
<tr><th>Opening</th><th>Games</th><th>White Win %</th><th>Black Win %</th><th>Draw %</th><th>Avg. Opening Depth</th><th>Avg. Game Length</th></tr>
{''.join(f'<tr><td>{op}</td><td>{opening_stats[op]["total"]:,}</td><td>{opening_stats[op]["white_pct"]}%</td><td>{opening_stats[op]["black_pct"]}%</td><td>{opening_stats[op]["draw_pct"]}%</td><td>{opening_stats[op]["avg_ply"]}</td><td>{opening_stats[op]["avg_turns"]}</td></tr>' for op in top_openings)}
</table>

<h3>Openings Where Black Outperforms White</h3>
<div class="stat-block">
  <p>Most openings favor White, consistent with the first-move advantage. However, among openings with at least 30 games, the following show Black outperforming White:</p>
</div>
{''.join(f'<div class="finding"><strong>{op}</strong>: Black wins {bp}% vs. White {wp}% ({total:,} games, +{round(bp - wp, 1)}pp Black edge)</div>' for op, wp, bp, total in black_favored[:8]) if black_favored else '<div class="stat-block"><p>No openings in the top 15 show a clear Black advantage at the 30-game threshold.</p></div>'}

<h3>Top 15 ECO Codes by Frequency</h3>
<div class="chart-row">
  <div class="chart-box full">
    <h4>Win Rate by ECO Code (Top 15)</h4>
    <div class="chart-container"><canvas id="chartECO"></canvas></div>
  </div>
</div>

<table>
<tr><th>ECO</th><th>Common Name</th><th>Games</th><th>White Win %</th><th>Black Win %</th><th>Draw %</th></tr>
{''.join(f'<tr><td>{eco}</td><td>{eco_stats[eco]["common_name"]}</td><td>{eco_stats[eco]["total"]:,}</td><td>{eco_stats[eco]["white_pct"]}%</td><td>{eco_stats[eco]["black_pct"]}%</td><td>{round(eco_stats[eco]["draws"] / eco_stats[eco]["total"] * 100, 1)}%</td></tr>' for eco in top_ecos)}
</table>

