            'avg_turns': round(subset['turns'].mean(), 1)
        }

# ============================================================
# SECTION 5: Time Control Patterns
# ============================================================
# Classify time controls
def classify_tc(tc):
    try:
        base = int(tc.split('+')[0])
    except:
        return 'Other'
    if base <= 3: return 'Bullet (1-3)'
    elif base <= 5: return 'Blitz (5)'
    elif base <= 10: return 'Rapid (10)'
    elif base <= 15: return 'Rapid (15)'
    elif base <= 30: return 'Classical (20-30)'
    else: return 'Classical (30+)'

df['tc_category'] = df['increment_code'].apply(classify_tc)

tc_cat_order = ['Bullet (1-3)', 'Blitz (5)', 'Rapid (10)', 'Rapid (15)', 'Classical (20-30)', 'Classical (30+)']

tc_cat_stats = {}
for cat in tc_cat_order:
    subset = df[df['tc_category'] == cat]
    total = len(subset)
    if total == 0:
        continue
    vs_dist = subset['victory_status'].value_counts(normalize=True).to_dict()
    vs_pct = {k: round(v * 100, 1) for k, v in vs_dist.items()}
    tc_cat_stats[cat] = {
        'total': total,
        'avg_turns': round(subset['turns'].mean(), 1),
        'median_turns': round(subset['turns'].median(), 1),
        'victory_status': vs_pct,
        'draw_pct': round(len(subset[subset['winner'] == 'draw']) / total * 100, 1),
        'white_pct': round(len(subset[subset['winner'] == 'white']) / total * 100, 1),
        'black_pct': round(len(subset[subset['winner'] == 'black']) / total * 100, 1)
    }

# Top individual time controls
top_tc_stats = {}
for tc in top_tcs:
    subset = df[df['increment_code'] == tc]
    total = len(subset)
    vs_dist = subset['victory_status'].value_counts(normalize=True).to_dict()
    vs_pct = {k: round(v * 100, 1) for k, v in vs_dist.items()}
    top_tc_stats[tc] = {
        'total': total,
        'avg_turns': round(subset['turns'].mean(), 1),
        'victory_status': vs_pct
    }

# ============================================================
# KPIs Summary
